"use client"

import * as React from "react"

/**
 * What a host asks Nessa to look like, and what Nessa resolved that to.
 *
 * The two are not the same value, and keeping them apart is the whole point.
 * `System` is a *request* — it means "follow the operating system" — and it
 * never reaches the DOM. What reaches the DOM is the resolution: light or
 * dark, never system. A DOM contract that could say "system" would leave
 * every selector asking a second question.
 */
export const NessaColorMode = {
  Light: "light",
  Dark: "dark",
  System: "system",
} as const

export type NessaColorMode =
  (typeof NessaColorMode)[keyof typeof NessaColorMode]

/** The two appearances a scope can actually be in. */
export type NessaResolvedColorMode =
  | typeof NessaColorMode.Light
  | typeof NessaColorMode.Dark

export interface NessaColorModeState {
  /** What was asked for, which may be `system`. */
  mode: NessaColorMode
  /** What that resolved to. Never `system`. */
  resolvedMode: NessaResolvedColorMode
  setMode: (mode: NessaColorMode) => void
}

/**
 * The resolved mode, published to everything inside a provider.
 *
 * `null` rather than a default state: a component reading this outside a
 * provider has a real problem — it is about to style itself against a mode
 * nobody chose — and a plausible-looking default would hide that.
 */
export const NessaColorModeContext =
  React.createContext<NessaColorModeState | null>(null)

/** The media query the `system` request follows. */
export const darkSchemeQuery = "(prefers-color-scheme: dark)"

/**
 * Reads the enclosing provider's requested and resolved mode.
 *
 * Components that only need to *look* right need none of this — that is what
 * the tokens are for. This is for the few that render something themselves in
 * one appearance or the other: a syntax highlighter choosing a theme, a
 * diagram renderer picking its palette.
 *
 * @throws When used outside a `NessaProvider`.
 */
export function useNessaColorMode(): NessaColorModeState {
  const state = React.useContext(NessaColorModeContext)
  if (!state) {
    throw new Error(
      "useNessaColorMode must be used inside a NessaProvider. Wrap the tree in <NessaProvider> so there is a resolved mode to read.",
    )
  }
  return state
}

/**
 * The resolved mode, or null outside a provider.
 *
 * For components that must keep working without one. A code block in an
 * application that has not adopted the provider still has to pick a syntax
 * theme, and throwing at it would make adoption all-or-nothing.
 */
export function useOptionalNessaColorMode(): NessaColorModeState | null {
  return React.useContext(NessaColorModeContext)
}

"use client"

import * as React from "react"
import { Slot } from "radix-ui"

/**
 * The parts a Nessa root and a nested theme scope share: what they put on
 * their element, and how they decide which element that is.
 *
 * Both render exactly one element carrying `data-nessa-*` attributes, and
 * both let a host supply that element with `asChild` rather than adding a
 * wrapper to a tree that already has a root. Keeping the mechanics here means
 * the two cannot drift on ownership rules — whose className wins, whose
 * attributes win, what happens to a style a host also set.
 */

/**
 * The finite set of UI sizes, as a preset rather than an arbitrary multiplier.
 * A number a host could type freely would make every component's geometry a
 * per-application question.
 */
export const NessaScale = {
  Smaller: "90",
  Small: "95",
  Default: "100",
  Large: "105",
  Larger: "110",
  Largest: "125",
} as const

export type NessaScale = (typeof NessaScale)[keyof typeof NessaScale]

/** Theme names are open strings: a host may publish its own. */
export type NessaThemeName = string

export interface NessaThemeState {
  theme: NessaThemeName
  scale: NessaScale
}

/** Theme identity, for the few surfaces that need to know which theme they are in. */
export const NessaThemeContext = React.createContext<NessaThemeState | null>(null)

export interface NessaScopeOwnProps {
  scale?: NessaScale
  className?: string
  style?: React.CSSProperties
  ref?: React.Ref<HTMLElement>
}

/**
 * Either Nessa renders its own element, or the host hands one over.
 *
 * `asChild` takes exactly one element, which is a type-level constraint
 * rather than advice: text has no attributes to carry, and two children would
 * leave the scope's identity ambiguous.
 */
export type NessaRootElementProps =
  | { asChild: true; children: React.ReactElement }
  | { asChild?: false; children?: React.ReactNode }

/** The attributes a scope owns, with anything undefined dropped. */
export function applyScopeProps(
  props: Record<string, unknown>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(props).filter(([, value]) => value !== undefined),
  )
}

interface ScopeElementOptions {
  asChild?: boolean
  children?: React.ReactNode
  ref?: React.Ref<HTMLElement>
  props: Record<string, unknown>
  /**
   * The declarations the scope owns outright, as opposed to the ones a host
   * merely passed through `props.style`. Only these outrank an `asChild`
   * child's own style; everything else keeps Slot's ordinary precedence,
   * where the child wins.
   */
  ownedStyle?: React.CSSProperties
  scopeName: string
}

/**
 * Renders the scope's single element: Nessa's own `div`, or the host's child.
 *
 * @returns The element, with the scope's attributes applied last so they win.
 */
export function useNessaScopeElement({
  asChild,
  children,
  ref,
  props,
  ownedStyle,
  scopeName,
}: ScopeElementOptions): React.ReactElement {
  useFragmentGuard(asChild, children, scopeName)
  useExistingScopeAttributeGuard(asChild, children, scopeName)
  const hostStyle = props.style as React.CSSProperties | undefined
  if (asChild) {
    // Reconciled onto the *child*, because Slot does not do what it looks like
    // it does: `mergeProps` returns `{...slotProps, ...childProps}`, so for any
    // prop that is not a handler, `style` or `className`, the child wins.
    // Passing the scope's attributes only to the Slot would let a child declare
    // `data-nessa-mode="light"` inside a Dark provider — React context saying
    // one thing while the DOM and the native controls say another — or keep
    // `system` on the element, defeating the Light-or-Dark invariant the whole
    // contract rests on.
    //
    // Clearing the child's copies is not enough either: a prop cloned as
    // `undefined` is still an own key of `childProps`, so it wins the same
    // merge and removes the attribute the scope was trying to write. The
    // scope's own values therefore go onto the child too, on the winning side
    // of the merge, and land on the element. A `data-nessa-*` the child brought
    // that the scope does not own is cleared rather than replaced, since the
    // scope owns the whole prefix. Everything else the child brought is left
    // alone.
    const child = children as React.ReactElement<Record<string, unknown>>
    const childProps = (child.props ?? {}) as Record<string, unknown>
    const childStyle = childProps.style as React.CSSProperties | undefined
    const reconciled = React.cloneElement(child, {
      ...Object.fromEntries(
        Object.keys(childProps)
          .filter((key) => key.startsWith("data-nessa-"))
          .map((key) => [key, undefined]),
      ),
      ...Object.fromEntries(
        Object.entries(props).filter(([key]) => key.startsWith("data-nessa-")),
      ),
      // Ownership stops where the scope's own declarations stop. A `style` a
      // host passed to the scope is an ordinary style and loses to the child's
      // in the usual way; only what the scope owns — `color-scheme`, which has
      // to agree with the attributes beside it — outranks the child.
      style: { ...hostStyle, ...childStyle, ...ownedStyle },
    } as Record<string, unknown>)
    return (
      <Slot.Root {...props} ref={ref}>
        {reconciled}
      </Slot.Root>
    )
  }
  return (
    <div
      {...props}
      style={{ ...hostStyle, ...ownedStyle }}
      ref={ref as React.Ref<HTMLDivElement>}
    >
      {children}
    </div>
  )
}

/**
 * A Fragment has no element to carry the scope, so `asChild` onto one
 * silently produces a tree with no theme at all — the failure looks like a
 * styling bug rather than a composition one.
 */
function useFragmentGuard(
  asChild: boolean | undefined,
  children: React.ReactNode,
  scopeName: string,
) {
  React.useEffect(() => {
    if (process.env.NODE_ENV === "production" || !asChild) return
    if (React.isValidElement(children) && children.type !== React.Fragment) return
    console.warn(
      `${scopeName} with \`asChild\` needs one element that renders a DOM node; a Fragment has nothing to put the scope's attributes on.`,
    )
  }, [asChild, children, scopeName])
}

/**
 * A child that already carries `data-nessa-*` is being overwritten, and the
 * host deserves to know which of the two values is going to win.
 */
function useExistingScopeAttributeGuard(
  asChild: boolean | undefined,
  children: React.ReactNode,
  scopeName: string,
) {
  React.useEffect(() => {
    if (process.env.NODE_ENV === "production" || !asChild) return
    if (!React.isValidElement(children)) return
    const childProps = children.props as Record<string, unknown>
    const existing = Object.keys(childProps).filter((key) =>
      key.startsWith("data-nessa-"),
    )
    if (!existing.length) return
    console.warn(
      `${scopeName} owns ${existing.join(", ")}; the value on its \`asChild\` child is dropped so the scope's own wins.`,
    )
  }, [asChild, children, scopeName])
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { PortalContainerProvider } from "@/lib/portal-container"
import {
  NessaColorMode,
  NessaColorModeContext,
  darkSchemeQuery,
  type NessaColorModeState,
  type NessaResolvedColorMode,
} from "./nessa-color-mode"
import {
  NessaScale,
  NessaThemeContext,
  applyScopeProps,
  useNessaScopeElement,
  type NessaRootElementProps,
  type NessaScopeOwnProps,
  type NessaThemeName,
} from "./nessa-scope"

/**
 * The root of a Nessa tree: one element carrying the theme, the resolved
 * appearance, and the scale, and one context publishing the mode to whatever
 * inside needs to render in it.
 *
 * It owns exactly one DOM element and nothing else. It does not touch
 * `documentElement`, it does not touch `body`, and it writes no layout rules —
 * a design system that reached for the document would be unable to appear
 * twice on one page, or inside a host that owns its own root.
 *
 * That includes the floating layers opened inside it. A menu keeps going
 * wherever it was already going and carries the scope's attributes with it,
 * rather than being moved under the scope to be themed by ancestry: moving it
 * would hand the root's `overflow`, `transform` and layout to a layer that
 * wants none of them, and a provider embedded in a host's own clipping box
 * would clip every menu opened in it.
 *
 * `data-nessa-mode` is the contract every dark token selector matches, and it
 * is always `light` or `dark`. A `system` *request* stays in React state; what
 * the DOM records is what it resolved to. That is what lets a light scope sit
 * inside a dark one and resolve independently: the selector matches the
 * nearest scope's own attribute rather than any dark ancestor.
 */

export type NessaControlledColorMode = {
  mode: NessaColorMode
  /**
   * The appearance the application resolved `system` to, typically from a
   * server-rendered cookie. Supplying it means Nessa registers no media
   * listener at all and takes the application's word.
   */
  resolvedMode?: NessaResolvedColorMode
  onModeChange: (mode: NessaColorMode) => void
  defaultMode?: never
  defaultResolvedMode?: never
}

export type NessaUncontrolledColorMode = {
  mode?: never
  resolvedMode?: never
  defaultMode?: NessaColorMode
  /**
   * What `system` renders as on the server and the first client render,
   * before `matchMedia` can be consulted. An initial-state input only:
   * changing it later does nothing, and re-entering `system` never reuses it.
   */
  defaultResolvedMode?: NessaResolvedColorMode
  onModeChange?: (mode: NessaColorMode) => void
}

export type NessaProviderProps = NessaScopeOwnProps &
  NessaRootElementProps &
  (NessaControlledColorMode | NessaUncontrolledColorMode) & {
    theme?: NessaThemeName
  }

function NessaProvider({
  theme = "default",
  scale = NessaScale.Default,
  className,
  style,
  ref,
  children,
  asChild,
  ...colorMode
}: NessaProviderProps) {
  const {
    mode: controlledMode,
    resolvedMode: suppliedResolvedMode,
    defaultMode,
    defaultResolvedMode,
    onModeChange,
    // Read through one permissive shape rather than the discriminated union.
    // Intersecting the two would give `onModeChange` a type that is both
    // optional and required and callable as neither; the union's job is to
    // stop a *caller* mixing controlled and uncontrolled props, and it has
    // already done that by the time the props are here.
  } = colorMode as {
    mode?: NessaColorMode
    resolvedMode?: NessaResolvedColorMode
    defaultMode?: NessaColorMode
    defaultResolvedMode?: NessaResolvedColorMode
    onModeChange?: (mode: NessaColorMode) => void
  }

  const isControlled = controlledMode !== undefined
  const [uncontrolledMode, setUncontrolledMode] = React.useState<NessaColorMode>(
    defaultMode ?? NessaColorMode.System,
  )
  const mode = isControlled ? controlledMode : uncontrolledMode

  // Only an unsupplied `system` request listens. A controlled resolution is
  // the application's answer and Nessa must not second-guess it; an explicit
  // light or dark has nothing to follow.
  const followsSystem =
    mode === NessaColorMode.System && suppliedResolvedMode === undefined

  // The appearance `system` last resolved to. Seeded from the application's
  // value where there is one, so a server-rendered dark page hydrates dark
  // instead of flashing light on the way to the same answer.
  const [systemResolved, setSystemResolved] = React.useState<NessaResolvedColorMode>(
    suppliedResolvedMode ?? defaultResolvedMode ?? NessaColorMode.Light,
  )

  // The appearance actually committed, whatever produced it.
  //
  // Written in an effect rather than during render, so a concurrent render
  // that React throws away cannot leave its appearance behind as the
  // committed one. Read during render only by the handoff below, and only for
  // the value the last commit put on screen.
  const committedResolved = React.useRef<NessaResolvedColorMode>(
    mode === NessaColorMode.System
      ? (suppliedResolvedMode ?? defaultResolvedMode ?? NessaColorMode.Light)
      : mode,
  )

  // Entering unsupplied `system` hands over to what is on screen rather than
  // to the initial seed: the seed answers "what should the first paint be",
  // which is a different question from "what is on screen right now", and a
  // Dark page switching to `system` under a Dark OS would otherwise publish
  // Dark → Light → Dark and flash white on the way to the answer it already
  // had. `matchMedia` is sampled in the effect below, a commit later; until
  // then the committed appearance is a better answer than a stale seed.
  //
  // Adjusted during render, not in an effect. An effect runs after the commit,
  // so the wrong appearance would already be on the element and in context by
  // the time it could repair anything — the very transition being avoided.
  // Re-rendering from the render phase is React's own answer to exactly this:
  // the intermediate output is discarded rather than committed, so nothing
  // downstream ever sees the stale value.
  const [wasFollowingSystem, setWasFollowingSystem] = React.useState(followsSystem)
  if (followsSystem !== wasFollowingSystem) {
    setWasFollowingSystem(followsSystem)
    if (followsSystem && systemResolved !== committedResolved.current) {
      setSystemResolved(committedResolved.current)
    }
  }

  const resolvedMode: NessaResolvedColorMode =
    mode === NessaColorMode.System
      ? (suppliedResolvedMode ?? systemResolved)
      : mode

  React.useEffect(() => {
    committedResolved.current = resolvedMode
  }, [resolvedMode])

  React.useEffect(() => {
    if (!followsSystem || typeof window === "undefined" || !window.matchMedia) {
      return
    }
    const media = window.matchMedia(darkSchemeQuery)
    // Sampled synchronously as well as subscribed: between the render that
    // entered `system` and this effect the OS may already disagree with the
    // handoff, and waiting for a change event would leave the wrong appearance
    // on screen until the user changed their mind.
    setSystemResolved(media.matches ? NessaColorMode.Dark : NessaColorMode.Light)
    // A generation, so an event queued before a mode change cannot commit
    // after it. Leaving `system` invalidates the listener on the way out;
    // without this a late event would drag an explicit Light back to Dark.
    let current = true
    const onChange = (event: MediaQueryListEvent) => {
      if (!current) return
      setSystemResolved(event.matches ? NessaColorMode.Dark : NessaColorMode.Light)
    }
    media.addEventListener("change", onChange)
    return () => {
      current = false
      media.removeEventListener("change", onChange)
    }
  }, [followsSystem])

  const setMode = React.useCallback(
    (next: NessaColorMode) => {
      if (!isControlled) setUncontrolledMode(next)
      onModeChange?.(next)
    },
    [isControlled, onModeChange],
  )

  const colorModeState = React.useMemo<NessaColorModeState>(
    () => ({ mode, resolvedMode, setMode }),
    [mode, resolvedMode, setMode],
  )
  const themeState = React.useMemo(() => ({ theme, scale }), [scale, theme])
  // The theme every floating layer below here carries onto its own element.
  // Panels that own a boundary — a Sheet, a reading view — still publish
  // their own container nearer the layer and keep it: where a layer lands is
  // their question, and this only answers what it looks like when it gets
  // there.
  const layerScope = React.useMemo(
    () => ({
      "data-nessa-theme": theme,
      "data-nessa-mode": resolvedMode,
      "data-nessa-scale": scale,
    }),
    [resolvedMode, scale, theme],
  )

  useControlledModeWarning(isControlled)
  useResolutionPropWarning(mode, suppliedResolvedMode, defaultResolvedMode)

  const element = useNessaScopeElement({
    asChild,
    children,
    ref,
    props: applyScopeProps({
      "data-nessa-root": "",
      "data-nessa-theme": theme,
      "data-nessa-mode": resolvedMode,
      "data-nessa-scale": scale,
      className: cn(className),
      style,
    }),
    // Nessa keeps ownership of `color-scheme` even when a host supplies
    // styles: it is what makes form controls, scrollbars and the canvas
    // itself agree with the tokens, and a scope whose controls disagree with
    // its surface reads as broken rather than as themed. It is the only
    // declaration the scope owns, so it is the only one that outranks an
    // `asChild` child's own.
    ownedStyle: { colorScheme: resolvedMode },
    scopeName: "NessaProvider",
  })

  return (
    <NessaThemeContext.Provider value={themeState}>
      <NessaColorModeContext.Provider value={colorModeState}>
        <PortalContainerProvider container={null} scope={layerScope}>
          {element}
        </PortalContainerProvider>
      </NessaColorModeContext.Provider>
    </NessaThemeContext.Provider>
  )
}

/** Warns once when a host switches between controlled and uncontrolled mode. */
function useControlledModeWarning(isControlled: boolean) {
  const initial = React.useRef(isControlled)
  React.useEffect(() => {
    if (process.env.NODE_ENV === "production") return
    if (initial.current === isControlled) return
    const was = initial.current
    initial.current = isControlled
    console.warn(
      `NessaProvider changed from ${was ? "controlled" : "uncontrolled"} to ${isControlled ? "controlled" : "uncontrolled"} mode. Pick one for the life of the provider: supply \`mode\` with \`onModeChange\`, or supply neither.`,
    )
  }, [isControlled])
}

/**
 * Warns when a resolution prop is supplied alongside an explicit mode, where
 * it means nothing and is almost always a mistaken attempt to force an
 * appearance.
 */
function useResolutionPropWarning(
  mode: NessaColorMode,
  resolvedMode: NessaResolvedColorMode | undefined,
  defaultResolvedMode: NessaResolvedColorMode | undefined,
) {
  React.useEffect(() => {
    if (process.env.NODE_ENV === "production") return
    if (mode === NessaColorMode.System) return
    if (resolvedMode === undefined && defaultResolvedMode === undefined) return
    console.warn(
      `NessaProvider ignores \`resolvedMode\`/\`defaultResolvedMode\` while \`mode\` is "${mode}": they only answer what "system" resolves to. Set \`mode\` itself to force an appearance.`,
    )
  }, [defaultResolvedMode, mode, resolvedMode])
}

export { NessaProvider }
